// src/App.js
import React, { useState } from 'react';
import CourseList from './CourseList';   // 교수님용 수강신청 페이지
import AdminPage from './AdminPage';     // 관리자 페이지 (기존 파일 유지)
import SummaryPage from './SummaryPage'; // 시수 통계 페이지

function App() {
  const [currentPage, setCurrentPage] = useState('list');

  // 화면 전환 함수
  const handleNavigate = (page) => {
    setCurrentPage(page);
  };

  return (
    <div>
      {/* 상단 탭 메뉴 삭제됨 */}

      {/* 2. 선택된 페이지 보여주기 */}
      <div style={{ padding: '0' }}>
        {currentPage === 'list' && (
          <CourseList onNavigate={handleNavigate} />
        )}
        
        {currentPage === 'admin' && (
          <div style={{ padding: '20px' }}>
            <button 
              onClick={() => setCurrentPage('list')}
              style={{ marginBottom:'20px', padding:'10px', cursor:'pointer', border:'1px solid #ccc', background:'#fff', borderRadius:'5px' }}
            >
              ⬅️ 메인으로 돌아가기
            </button>
            <AdminPage />
          </div>
        )}

        {currentPage === 'summary' && (
          <SummaryPage onNavigate={handleNavigate} />
        )}
      </div>
    </div>
  );
}

export default App;